std::latch done{2}; int results[2] = {};
for (int r = 1; r <= 3; ++r) {
  std::thread a([&] { results[0] = r * 10;
    done.count_down(); });
  std::thread b([&] { results[1] = r*10 + 1;
    done.count_down(); });
  done.wait();
  std::cout << "round " << r << ": "
    << results[0] + results[1] << '\n';
  a.join(); b.join();
}

int results[2] = {};
for (int r = 1; r <= 3; ++r) {
  std::latch done{2};  // fresh each round
  std::jthread a([&] { results[0] = r * 10;
                       done.count_down(); });
  std::jthread b([&] { results[1] = r * 10 + 1;
                       done.count_down(); });
  done.wait();
  std::cout << "round " << r << ": "
            << results[0] + results[1] << '\n';
}  // jthreads join, then the latch dies

